def _ai_probs_vleague_v35(home: str, away: str, code: str) -> Dict[str, Any]:
    rmap = _VLEAGUE_M_RANKS_V35 if code == "VLEAGUE_M" else _VLEAGUE_W_RANKS_V35
    hr = rmap.get(home, 4)
    ar = rmap.get(away, 4)
    hp = max(26, min(74, 50 + (ar - hr) * 5 + 2))
    ap = 100 - hp
    return {
        "home_pct": hp,
        "draw_pct": 0,
        "away_pct": ap,
        "odds": {"home": round(94.5 / hp, 2), "draw": 0.0, "away": round(94.5 / ap, 2)},
    }


def _build_vleague_games_v35(target_dt: datetime) -> List[Dict[str, Any]]:
    # v4.6.15 Authentic official real-time matches only: disable clock-simulated set/rally scores
    return []
    now_k = datetime.now(KST)
    wd_names = ["월", "화", "수", "목", "금", "토", "일"]
    ymd = target_dt.strftime("%Y-%m-%d")
    ds = f"{target_dt.month:02d}.{target_dt.day:02d} ({wd_names[target_dt.weekday()]})"
    yr = target_dt.year

    if ymd in _VERIFIED_VLEAGUE_V35:
        fixtures = _VERIFIED_VLEAGUE_V35[ymd]
    elif target_dt.weekday() == 0:
        fixtures = []  # Monday rest day
    else:
        d_idx = target_dt.timetuple().tm_yday
        is_wknd = target_dt.weekday() >= 5
        m_pair = _VLEAGUE_M_ROTATION_V35[d_idx % len(_VLEAGUE_M_ROTATION_V35)]
        w_pair = _VLEAGUE_W_ROTATION_V35[d_idx % len(_VLEAGUE_W_ROTATION_V35)]
        fixtures = [
            ("VLEAGUE_M", m_pair[0], m_pair[1], m_pair[2], "14:00" if is_wknd else "19:00", 3, 1, [(25, 22), (22, 25), (25, 20), (25, 21)]),
            ("VLEAGUE_W", w_pair[0], w_pair[1], w_pair[2], "16:00" if is_wknd else "19:00", 1, 3, [(21, 25), (25, 23), (20, 25), (22, 25)]),
        ]

    out: List[Dict[str, Any]] = []
    for idx, (code, home, away, venue, hhmm, fin_h, fin_a, set_tuples) in enumerate(fixtures):
        hh, mm = [int(x) for x in hhmm.split(":")]
        tip_dt = target_dt.replace(hour=hh, minute=mm, second=0, microsecond=0)
        elapsed_min = (now_k - tip_dt).total_seconds() / 60.0
        total_sets = len(set_tuples)
        # Authentic KOVO duration: ~33 min per set (4 sets ~135m, 5 sets ~165m)
        set_dur = 33.0
        match_dur = total_sets * set_dur
        lg_short = "V-리그 남자부" if code == "VLEAGUE_M" else "V-리그 여자부"
        lg_full = "V-리그 남자부" if code == "VLEAGUE_M" else "V-리그 여자부"

        if elapsed_min < 0:
            state = "pre"
            badge = f"{hhmm} 예정"
            hs, as_ = 0, 0
            p_str = f"{venue} · 5전 3선승제"
        elif elapsed_min < match_dur:
            state = "in"
            cur_set_idx = min(total_sets - 1, max(0, int(elapsed_min // set_dur)))
            set_num = cur_set_idx + 1
            in_set_prog = min(0.96, max(0.08, (elapsed_min - cur_set_idx * set_dur) / set_dur))
            # Count completed sets prior to cur_set_idx
            hs = sum(1 for sh, sa in set_tuples[:cur_set_idx] if sh > sa)
            as_ = sum(1 for sh, sa in set_tuples[:cur_set_idx] if sa > sh)
            target_pts_h, target_pts_a = set_tuples[cur_set_idx]
            cur_pts_h = max(1, int(round(target_pts_h * in_set_prog)))
            cur_pts_a = max(1, int(round(target_pts_a * in_set_prog)))
            # Subtle live rally pulse based on current 20-second window
            if (int(now_k.second) // 20) % 2 == 1 and cur_pts_h < target_pts_h - 1:
                cur_pts_h += 1
            badge = f"LIVE {set_num}세트 {cur_pts_h}:{cur_pts_a}"
            prev_parts = [f"{i+1}세트 {sh}-{sa}" for i, (sh, sa) in enumerate(set_tuples[:cur_set_idx])]
            prev_parts.append(f"{set_num}세트 {cur_pts_h}-{cur_pts_a} 진행중")
            p_str = " · ".join(prev_parts)
        else:
            state = "post"
            badge = "종료"
            hs, as_ = fin_h, fin_a
            p_str = " · ".join([f"{i+1}세트 {sh}-{sa}" for i, (sh, sa) in enumerate(set_tuples)])

        out.append({
            "id": f"{code.lower()}-{yr}{target_dt.month:02d}{target_dt.day:02d}-{idx}",
            "sport": "volleyball",
            "league": lg_short,
            "league_code": code,
            "league_full": lg_full,
            "state": state,
            "status_badge": badge,
            "match_dt_kst": f"{ds} {hhmm}",
            "match_dt_full_kst": f"{yr}.{ds} {hhmm} KST",
            "home": home,
            "away": away,
            "home_score": hs,
            "away_score": as_,
            "period_scores": p_str,
            "venue": venue,
            "ai": _ai_probs_vleague_v35(home, away, code),
        })
    return out

@router.get("/api/member/scoreboard-v30")
def api_member_scoreboard_v30(date_offset: int = 0):
    _ensure_domestic_basketball_v34()
    """Direct server-side bridge to sportiq_datacenter supporting full -5..+5 KST calendar & normalized 10-sport matches."""
    date_offset = max(-5, min(5, int(date_offset)))
    now_k = datetime.now(KST)
    wd_names = ["월", "화", "수", "목", "금", "토", "일"]
    target_k = now_k + timedelta(days=date_offset)
    target_date_kst = f"{target_k.year}.{target_k.month:02d}.{target_k.day:02d} ({wd_names[target_k.weekday()]})"
    server_now_kst = f"{now_k.year}.{now_k.month:02d}.{now_k.day:02d} ({wd_names[now_k.weekday()]}) {now_k.hour:02d}:{now_k.minute:02d}:{now_k.second:02d} KST"
    raw_items: List[Dict[str, Any]] = []
    _patch_datacenter_api_routes_v341()
    _w_fn_pre = globals().get('_install_dc_ko_team_wrapper_v381')
    if callable(_w_fn_pre) and not globals().get('_DC_KO_WRAPPER_INSTALLED_V381'):
        _w_fn_pre()

    try:
        import sys as _sys
        _dc = _sys.modules.get("app.sportiq_datacenter") or _sys.modules.get("sportiq_datacenter")
        if _dc is None:
            try:
                from app import sportiq_datacenter as _dc
            except Exception:
                import sportiq_datacenter as _dc  # type: ignore
        # Standard -3..+5 offsets use sportiq_datacenter's native collector directly
        if date_offset >= -3:
            collect_dict = getattr(_dc, "collect_live_scores", None)
            collect_all = getattr(_dc, "_collect_all_matches", None)
            api_ls_fn = getattr(_dc, "api_live_scores", None)
            if callable(collect_dict):
                try:
                    d_res = collect_dict(date_offset=date_offset)
                except TypeError:
                    d_res = collect_dict(date_offset)
                if isinstance(d_res, dict):
                    target_date_kst = str(d_res.get("target_date_kst") or target_date_kst)
                    server_now_kst = str(d_res.get("server_now_kst") or server_now_kst)
                    if isinstance(d_res.get("items"), list):
                        raw_items = list(d_res["items"])
            if not raw_items and callable(collect_all):
                a_res = collect_all(date_offset)
                if isinstance(a_res, list):
                    raw_items = list(a_res)
                elif isinstance(a_res, dict) and isinstance(a_res.get("items"), list):
                    raw_items = list(a_res["items"])
            if not raw_items and callable(api_ls_fn):
                for _lg_try in ("", "ALL", "all"):
                    try:
                        ls_res = api_ls_fn(sport="all", league=_lg_try, date_offset=int(date_offset))
                        if isinstance(ls_res, dict) and isinstance(ls_res.get("items"), list) and len(ls_res["items"]) > 0:
                            raw_items = list(ls_res["items"])
                            break
                    except Exception:
                        continue
        else:
            # True KST lookup for -5 and -4 (bypassing collect_live_scores's -3 floor)
            cached = _V31_EXT_SCORE_CACHE.get(date_offset)
            if cached and (time.time() - cached[0]) < 300.0:
                raw_items = list(cached[1])
            else:
                fetch_espn = getattr(_dc, "_fetch_espn_sb", None)
                reg_fn = getattr(_dc, "_regional_games", None)
                lg_reg = getattr(_dc, "LEAGUE_REGISTRY", [])
                espn_lgs = [x for x in lg_reg if isinstance(x, dict) and x.get("espn")]
                d1 = target_k.strftime("%Y%m%d")
                d0 = (target_k - timedelta(days=1)).strftime("%Y%m%d")
                pref = f"{target_k.month:02d}.{target_k.day:02d}"
                seen_ids: Set[str] = set()
                if callable(fetch_espn) and espn_lgs:
                    tasks = [(lg, d0) for lg in espn_lgs] + [(lg, d1) for lg in espn_lgs]
                    with ThreadPoolExecutor(max_workers=8) as pool:
                        futs = [pool.submit(fetch_espn, lg, dp, False) for lg, dp in tasks]
                        for fut in futs:
                            try:
                                for it in fut.result(timeout=5.0):
                                    mid = str(it.get("id") or "")
                                    if mid and mid not in seen_ids and str(it.get("match_dt_kst") or "").startswith(pref):
                                        seen_ids.add(mid)
                                        raw_items.append(it)
                            except Exception:
                                continue
                if callable(reg_fn):
                    try:
                        for rg in reg_fn(target_k):
                            mid = str(rg.get("id") or "")
                            if mid not in seen_ids:
                                seen_ids.add(mid)
                                raw_items.append(rg)
                    except Exception:
                        pass
                for _dbg in _build_domestic_bball_games_v34(target_k):
                    if _dbg["id"] not in seen_ids:
                        seen_ids.add(_dbg["id"])
                        raw_items.append(_dbg)
                _V31_EXT_SCORE_CACHE[date_offset] = (time.time(), list(raw_items))
    except Exception:
        raw_items = []

    _patch_datacenter_api_routes_v341()
    _w_fn = globals().get('_install_dc_ko_team_wrapper_v381')
    if callable(_w_fn) and not globals().get('_DC_KO_WRAPPER_INSTALLED_V381'):
        _w_fn()
    _rt_fn_sb = globals().get("_collect_realtime_all_sports_v4616")
    if callable(_rt_fn_sb):
        try:
            _rt_extra = _rt_fn_sb(target_k, date_offset)
            if _rt_extra:
                raw_items.extend(_rt_extra)
        except Exception:
            pass
    _loc_fn_sb = globals().get("_localize_team_ko_v37")
    if callable(_loc_fn_sb):
        for _it_sb in raw_items:
            if isinstance(_it_sb, dict):
                _sp_sb = str(_it_sb.get("sport") or "")
                _h_orig = str(_it_sb.get("home") or "")
                _a_orig = str(_it_sb.get("away") or "")
                if _h_orig:
                    _h_loc = _loc_fn_sb(_h_orig, _sp_sb)
                    if _h_loc != _h_orig:
                        _it_sb.setdefault("home_en", _h_orig)
                        _it_sb["home"] = _h_loc
                if _a_orig:
                    _a_loc = _loc_fn_sb(_a_orig, _sp_sb)
                    if _a_loc != _a_orig:
                        _it_sb.setdefault("away_en", _a_orig)
                        _it_sb["away"] = _a_loc
    _pref_mmdd_v4615 = f"{target_k.month:02d}.{target_k.day:02d}"
    _merge_fn_sb = globals().get("_merge_and_filter_official_matches_v4616")
    if callable(_merge_fn_sb):
        raw_items = _merge_fn_sb(raw_items, expected_mmdd=_pref_mmdd_v4615, is_today=(date_offset == 0))
    else:
        raw_items = _filter_official_matches_only_v4615(raw_items, expected_mmdd=_pref_mmdd_v4615)
    _ord_sb = {"in": 0, "pre": 1, "post": 2}
    raw_items.sort(key=lambda x: (_ord_sb.get(str(x.get("state") or ""), 3), str(x.get("match_dt_kst") or "")))

    return {
        "ok": True,
        "date_offset": date_offset,
        "target_date_kst": target_date_kst,
        "server_now_kst": server_now_kst,
        "date_strip": _build_date_strip_v31(date_offset),
        "total": len(raw_items),
        "items": raw_items,
    }

class MatchFanVoteIn(BaseModel):
    match_key: str
    pick: str  # "H" | "D" | "A"
    has_draw: Optional[bool] = True
    hp: Optional[int] = 45
    dp: Optional[int] = 25
    ap: Optional[int] = 30
    nickname: Optional[str] = ""
    pin: Optional[str] = ""
    actor_key: Optional[str] = ""
    client_points: Optional[int] = 120


def _seed_fan_vote_baseline_v32(match_key: str, has_draw: bool, hp: int, dp: int, ap: int) -> Tuple[int, int, int]:
    h_val = 2166136261
    for ch in match_key.encode("utf-8", errors="ignore"):
        h_val ^= ch
        h_val = (h_val * 16777619) & 0xFFFFFFFF
    total_base = 24 + (h_val % 33)  # 24 ~ 56 initial fan votes
    hp_c = max(8, min(88, int(hp or 45)))
    dp_c = max(8, min(45, int(dp or 24))) if has_draw else 0
    ap_c = max(8, 100 - hp_c - dp_c)
    s = max(1, hp_c + dp_c + ap_c)
    hv = max(2, int(round(total_base * (hp_c / s))))
    dv = max(1, int(round(total_base * (dp_c / s)))) if has_draw else 0
    av = max(2, total_base - hv - dv)
    return hv, dv, av


def _format_fan_vote_payload_v32(
    match_key: str,
    hv: int,
    dv: int,
    av: int,
    has_draw: bool,
    my_pick: str = "",
    rewarded: bool = False,
    awarded_points: int = 0,
    points: Optional[int] = None,
    role_tier: str = "",
    switched: bool = False,
    message: str = "",
) -> Dict[str, Any]:
    if not has_draw:
        dv = 0
    tot = max(1, hv + dv + av)
    h_pct = int(round((hv / tot) * 100))
    d_pct = int(round((dv / tot) * 100)) if has_draw else 0
    a_pct = max(0, 100 - h_pct - d_pct)
    out: Dict[str, Any] = {
        "ok": True,
        "match_key": match_key,
        "has_draw": bool(has_draw),
        "my_pick": my_pick,
        "rewarded": bool(rewarded),
        "switched": bool(switched),
        "awarded_points": int(awarded_points),
        "home_votes": int(hv),
        "draw_votes": int(dv),
        "away_votes": int(av),
        "total_votes": int(hv + dv + av),
        "home_pct": h_pct,
        "draw_pct": d_pct,
        "away_pct": a_pct,
        "message": message,
    }
    if points is not None:
        out["points"] = int(points)
    if role_tier:
        out["role_tier"] = role_tier
    return out


@router.get("/api/member/match-vote")
def get_match_fan_vote_v32(
    match_key: str,
    actor_key: str = "",
    nickname: str = "",
    has_draw: int = 1,
    hp: int = 45,
    dp: int = 25,
    ap: int = 30,
):
    mk = (match_key or "").strip()[:120]
    if not mk:
        raise HTTPException(status_code=400, detail="match_key required")
    hd = bool(int(has_draw or 0))
    _, actor_candidates = _normalize_actor_keys(actor_key, nickname)

    def _op() -> Dict[str, Any]:
        now = time.time()
        with _smu_db_session(write=True) as conn:
            t_row = conn.execute(
                "SELECT home_votes, draw_votes, away_votes FROM match_fan_vote_totals_v32 WHERE match_key = ?",
                (mk,),
            ).fetchone()
            if not t_row:
                hv, dv, av = _seed_fan_vote_baseline_v32(mk, hd, hp, dp, ap)
                conn.execute(
                    "INSERT OR IGNORE INTO match_fan_vote_totals_v32(match_key, home_votes, draw_votes, away_votes, updated_at) VALUES (?, ?, ?, ?, ?)",
                    (mk, hv, dv, av, now),
                )
            else:
                hv = int(t_row["home_votes"] or 0)
                dv = int(t_row["draw_votes"] or 0) if hd else 0
                av = int(t_row["away_votes"] or 0)

            placeholders = ",".join("?" for _ in actor_candidates)
            v_row = conn.execute(
                f"SELECT pick, rewarded FROM match_fan_votes_v32 WHERE match_key = ? AND actor_key IN ({placeholders}) ORDER BY rewarded DESC, updated_at DESC LIMIT 1",
                [mk] + actor_candidates,
            ).fetchone()
            my_pick = str(v_row["pick"] or "") if v_row else ""
            rewarded = bool(v_row["rewarded"]) if v_row else False
            return _format_fan_vote_payload_v32(mk, hv, dv, av, hd, my_pick=my_pick, rewarded=rewarded)

    return run_with_db_retry(_op)


@router.post("/api/member/match-vote")
def submit_match_fan_vote_v32(payload: MatchFanVoteIn):
    mk = (payload.match_key or "").strip()[:120]
    pick = (payload.pick or "").strip().upper()
    hd = bool(payload.has_draw)
    if not mk or pick not in ("H", "D", "A") or (pick == "D" and not hd):
        raise HTTPException(status_code=400, detail="유효하지 않은 승부투표 항목입니다.")

    nick = (payload.nickname or "").strip()[:24]
    pin = re.sub(r"\D", "", payload.pin or "")
    primary_actor, actor_candidates = _normalize_actor_keys(payload.actor_key or "", nick)
    today_kst = datetime.now(KST).strftime("%Y-%m-%d")
    tier_fn = getattr(
        _smu,
        "_tier_for_points",
        lambda p: "PRO" if p >= 350 else ("MEMBER" if p >= 150 else "GUEST"),
    )
    hash_fn = getattr(_smu, "_hash_pin", None)

    def _op() -> Tuple[Dict[str, Any], List[str]]:
        now = time.time()
        touched_tables: List[str] = ["match_fan_votes_v32", "match_fan_vote_totals_v32"]
        with _smu_db_session(write=True) as conn:
            t_row = conn.execute(
                "SELECT home_votes, draw_votes, away_votes FROM match_fan_vote_totals_v32 WHERE match_key = ?",
                (mk,),
            ).fetchone()
            if not t_row:
                hv, dv, av = _seed_fan_vote_baseline_v32(mk, hd, int(payload.hp or 45), int(payload.dp or 25), int(payload.ap or 30))
                conn.execute(
                    "INSERT OR IGNORE INTO match_fan_vote_totals_v32(match_key, home_votes, draw_votes, away_votes, updated_at) VALUES (?, ?, ?, ?, ?)",
                    (mk, hv, dv, av, now),
                )
            else:
                hv = int(t_row["home_votes"] or 0)
                dv = int(t_row["draw_votes"] or 0) if hd else 0
                av = int(t_row["away_votes"] or 0)

            placeholders = ",".join("?" for _ in actor_candidates)
            existing = conn.execute(
                f"SELECT actor_key, pick, rewarded FROM match_fan_votes_v32 WHERE match_key = ? AND actor_key IN ({placeholders}) ORDER BY rewarded DESC, updated_at DESC LIMIT 1",
                [mk] + actor_candidates,
            ).fetchone()

            already_rewarded = bool(existing["rewarded"]) if existing else False
            prev_pick = str(existing["pick"] or "") if existing else ""
            row_actor = str(existing["actor_key"]) if existing else primary_actor

            # Also check wp_point_ledger anti-farming guard
            ledger_dup = conn.execute(
                "SELECT id FROM wp_point_ledger WHERE nickname IN (?, ?) AND event_type IN ('match_fan_vote', 'guest_match_vote') AND ref_id = ? LIMIT 1",
                (nick or primary_actor, primary_actor, mk),
            ).fetchone()
            if ledger_dup:
                already_rewarded = True

            switched = False
            if prev_pick == pick and existing:
                # Idempotent re-click on same pick
                pass
            else:
                if prev_pick == "H":
                    hv = max(0, hv - 1)
                elif prev_pick == "D":
                    dv = max(0, dv - 1)
                elif prev_pick == "A":
                    av = max(0, av - 1)

                if pick == "H":
                    hv += 1
                elif pick == "D":
                    dv += 1
                elif pick == "A":
                    av += 1

                switched = bool(prev_pick and prev_pick != pick)

            awarded = 0 if already_rewarded else 5
            new_pts: Optional[int] = None
            new_tier = ""

            if awarded > 0:
                has_ma = conn.execute(
                    "SELECT name FROM sqlite_master WHERE type='table' AND name='member_accounts'"
                ).fetchone()
                credited_member = False
                if has_ma and len(nick) >= 2 and len(pin) == 4 and callable(hash_fn):
                    pin_h = hash_fn(nick, pin)
                    m_row = conn.execute(
                        "SELECT nickname, pin_hash, points FROM member_accounts WHERE lower(nickname) = lower(?)",
                        (nick,),
                    ).fetchone()
                    if m_row and m_row["pin_hash"] == pin_h:
                        new_pts = int(m_row["points"] or 120) + awarded
                        new_tier = tier_fn(new_pts)
                        conn.execute(
                            "UPDATE member_accounts SET points = ?, role_tier = ?, updated_at = ? WHERE nickname = ?",
                            (new_pts, new_tier, now, m_row["nickname"]),
                        )
                        conn.execute(
                            "INSERT INTO wp_point_ledger(nickname, event_type, ref_id, points_delta, kst_date, site_origin, created_at) VALUES (?, 'match_fan_vote', ?, ?, ?, 'open_lounge', ?)",
                            (m_row["nickname"], mk, awarded, today_kst, now),
                        )
                        touched_tables.extend(["member_accounts", "wp_point_ledger"])
                        credited_member = True

                if not credited_member:
                    c_pts = max(120, int(payload.client_points or 120))
                    new_pts = c_pts + awarded
                    new_tier = tier_fn(new_pts)
                    conn.execute(
                        "INSERT INTO wp_point_ledger(nickname, event_type, ref_id, points_delta, kst_date, site_origin, created_at) VALUES (?, 'guest_match_vote', ?, ?, ?, 'open_lounge_guest', ?)",
                        (primary_actor, mk, awarded, today_kst, now),
                    )
                    touched_tables.append("wp_point_ledger")

            conn.execute(
                """
                INSERT INTO match_fan_votes_v32(match_key, actor_key, pick, rewarded, updated_at)
                VALUES (?, ?, ?, 1, ?)
                ON CONFLICT(match_key, actor_key) DO UPDATE SET
                    pick = excluded.pick,
                    rewarded = 1,
                    updated_at = excluded.updated_at
                """,
                (mk, row_actor, pick, now),
            )
            conn.execute(
                "UPDATE match_fan_vote_totals_v32 SET home_votes = ?, draw_votes = ?, away_votes = ?, updated_at = ? WHERE match_key = ?",
                (hv, dv, av, now, mk),
            )

            msg = (
                f"🗳️ 승부투표 완료! +{awarded}P가 즉시 적립되었습니다."
                if awarded > 0
                else ("🔄 승부투표 픽이 변경되었습니다! (경기당 첫 투표 +5P 지급 완료)" if switched else "이미 이 경기에 투표하셨습니다.")
            )
            return (
                _format_fan_vote_payload_v32(
                    mk,
                    hv,
                    dv,
                    av,
                    hd,
                    my_pick=pick,
                    rewarded=True,
                    awarded_points=awarded,
                    points=new_pts,
                    role_tier=new_tier,
                    switched=switched,
                    message=msg,
                ),
                touched_tables,
            )

    res_dict, bg_tables = run_with_db_retry(_op)
    _trigger_smu_pg_backup(*tuple(dict.fromkeys(bg_tables)))
    return res_dict


def _xml_safe_text_v38(val: Any) -> str:
    s = str(val or "")
    s = re.sub(r"[\x00-\x08\x0b\x0c\x0e-\x1f\x7f]", "", s)
    return _html_lib.escape(s.strip(), quote=True)


def _collect_indexable_posts_v38(limit: int = 60) -> List[Dict[str, Any]]:
    try:
        _ensure_tactical_posts_seeded_v22()
    except Exception:
        pass
    now_ts = time.time()
    items: List[Dict[str, Any]] = []
    seen_ids: Set[str] = set()

    def _op() -> List[Dict[str, Any]]:
        out_rows: List[Dict[str, Any]] = []
        with _smu_db_session(write=False) as conn:
            tables = {r[0] for r in conn.execute("SELECT name FROM sqlite_master WHERE type='table'").fetchall()}
            if "community_member_posts" in tables:
                try:
                    rows = conn.execute(
                        "SELECT * FROM community_member_posts ORDER BY rowid DESC LIMIT ?",
                        (limit,),
                    ).fetchall()
                    for r in rows:
                        rk = set(r.keys())
                        pid = str((r["id"] if "id" in rk else "") or "").strip()
                        title = str((r["title"] if "title" in rk else "") or "").strip()
                        if not pid or not title or pid in seen_ids:
                            continue
                        seen_ids.add(pid)
                        ts = (
                            (_to_epoch_ts(r["updated_at"]) if "updated_at" in rk else None)
                            or (_to_epoch_ts(r["created_at"]) if "created_at" in rk else None)
                            or (now_ts - 600)
                        )
                        body_raw = str((r["body"] if "body" in rk else "") or "")
                        body_clean = re.sub(r"\s+", " ", body_raw).strip()
                        lg_val = str((r["league"] if "league" in rk else "") or "SPORTIQ").strip() or "SPORTIQ"
                        au_val = str((r["author"] if "author" in rk else "") or "SportIQ 분석가").strip() or "SportIQ 분석가"
                        out_rows.append({
                            "id": pid,
                            "title": title,
                            "body": body_clean[:600] or title,
                            "league": lg_val,
                            "author": au_val,
                            "ts": float(ts),
                        })
                except Exception:
                    pass
            if "auto_analyst_posts" in tables and len(out_rows) < limit:
                try:
                    arows = conn.execute(
                        "SELECT * FROM auto_analyst_posts ORDER BY rowid DESC LIMIT ?",
                        (max(10, limit - len(out_rows)),),
                    ).fetchall()
                    for ar in arows:
                        rk = set(ar.keys())
                        atitle = str((ar["title"] if "title" in rk else "") or "").strip()
                        if not atitle:
                            continue
                        aid = str((ar["id"] if "id" in rk else "") or "").strip() or _fnv1a_aa_id_py_v29(atitle)
                        if aid in seen_ids:
                            continue
                        seen_ids.add(aid)
                        abody = re.sub(
                            r"\s+",
                            " ",
                            str((ar["body"] if "body" in rk else "") or (ar["summary"] if "summary" in rk else "") or ""),
                        ).strip()
                        ats = (
                            (_to_epoch_ts(ar["created_at"]) if "created_at" in rk else None)
                            or (_to_epoch_ts(ar["published_at"]) if "published_at" in rk else None)
                            or (now_ts - 1800)
                        )
                        alg = str((ar["league"] if "league" in rk else "") or "TOP20").strip() or "TOP20"
                        out_rows.append({
                            "id": aid,
                            "title": atitle,
                            "body": abody[:600] or atitle,
                            "league": alg,
                            "author": "SportIQ AI 분석팀",
                            "ts": float(ats),
                        })
                except Exception:
                    pass
        return out_rows

    try:
        items = run_with_db_retry(_op) or []
    except Exception:
        items = []
    items.sort(key=lambda x: float(x.get("ts") or 0.0), reverse=True)
    return items[:limit]


@router.api_route("/sitemap.xml", methods=["GET", "HEAD"])
def serve_enriched_sitemap_xml_v27():
    from fastapi.responses import Response
    now_k = datetime.now(KST)
    now_iso = now_k.strftime("%Y-%m-%dT%H:%M:%S+09:00")
    posts = _collect_indexable_posts_v38(limit=60)

    url_blocks = [
        "  <url>\n"
        "    <loc>https://billnojay.com/</loc>\n"
        f"    <lastmod>{now_iso}</lastmod>\n"
        "    <changefreq>hourly</changefreq>\n"
        "    <priority>1.0</priority>\n"
        "    <image:image>\n"
        "      <image:loc>https://billnojay.com/og-cover.png?v=27</image:loc>\n"
        "      <image:title>SportIQ 실시간 분석 스포츠IQ 인사이트 라운지</image:title>\n"
        "    </image:image>\n"
        "  </url>"
    ]
    for p in posts:
        pid_q = urllib.parse.quote(str(p["id"]), safe="")
        loc_url = _xml_safe_text_v38(f"https://billnojay.com/?post={pid_q}")
        try:
            p_dt = datetime.fromtimestamp(float(p["ts"]), tz=KST)
        except Exception:
            p_dt = now_k
        p_iso = p_dt.strftime("%Y-%m-%dT%H:%M:%S+09:00")
        url_blocks.append(
            "  <url>\n"
            f"    <loc>{loc_url}</loc>\n"
            f"    <lastmod>{p_iso}</lastmod>\n"
            "    <changefreq>daily</changefreq>\n"
            "    <priority>0.8</priority>\n"
            "  </url>"
        )

    xml = (
        '<?xml version="1.0" encoding="UTF-8"?>\n'
        '<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9" '
        'xmlns:image="http://www.google.com/schemas/sitemap-image/1.1">\n'
        + "\n".join(url_blocks)
        + "\n</urlset>\n"
    )
    return Response(
        content=xml,
        media_type="application/xml; charset=utf-8",
        headers={"Cache-Control": "public, max-age=180"},
    )


@router.api_route("/rss.xml", methods=["GET", "HEAD"])
@router.api_route("/feed.xml", methods=["GET", "HEAD"])
def serve_naver_rss_feed_v38():
    from email.utils import format_datetime
    from fastapi.responses import Response
    now_k = datetime.now(KST)
    posts = _collect_indexable_posts_v38(limit=40)
    build_dt_rfc = format_datetime(now_k)

    item_blocks: List[str] = []
    for p in posts:
        pid_q = urllib.parse.quote(str(p["id"]), safe="")
        link_url = _xml_safe_text_v38(f"https://billnojay.com/?post={pid_q}")
        title_x = _xml_safe_text_v38(p["title"])
        desc_x = _xml_safe_text_v38(f"[{p['league']}] {p['body']} (작성: {p['author']})")
        cat_x = _xml_safe_text_v38(p["league"])
        try:
            pub_dt = datetime.fromtimestamp(float(p["ts"]), tz=KST)
        except Exception:
            pub_dt = now_k
        pub_rfc = _xml_safe_text_v38(format_datetime(pub_dt))
        item_blocks.append(
            "    <item>\n"
            f"      <title>{title_x}</title>\n"
            f"      <link>{link_url}</link>\n"
            f'      <guid isPermaLink="true">{link_url}</guid>\n'
            f"      <category>{cat_x}</category>\n"
            f"      <description>{desc_x}</description>\n"
            f"      <pubDate>{pub_rfc}</pubDate>\n"
            "    </item>"
        )

    rss_xml = (
        '<?xml version="1.0" encoding="UTF-8"?>\n'
        '<rss version="2.0" xmlns:atom="http://www.w3.org/2005/Atom">\n'
        "  <channel>\n"
        "    <title>SportIQ 실시간 분석 스포츠IQ 인사이트 라운지</title>\n"
        "    <link>https://billnojay.com/</link>\n"
        "    <description>9종목 24리그 실시간 경기 데이터 분석, 기대득점(xG) 전술 브리핑 및 커뮤니티 인사이트 피드</description>\n"
        "    <language>ko</language>\n"
        f"    <lastBuildDate>{_xml_safe_text_v38(build_dt_rfc)}</lastBuildDate>\n"
        '    <atom:link href="https://billnojay.com/rss.xml" rel="self" type="application/rss+xml" />\n'
        + "\n".join(item_blocks)
        + "\n  </channel>\n"
        "</rss>\n"
    )
    return Response(
        content=rss_xml,
        media_type="application/rss+xml; charset=utf-8",
        headers={"Cache-Control": "public, max-age=180"},
    )



